-- mPanel 008: backfill existing sites and finish integrity hardening.\ninsert into public.site_security_settings(user_id,site_id)\nselect s.user_id,s.id from public.sites s\non conflict(site_id) do nothing;\n\ninsert into public.site_performance_settings(user_id,site_id)\nselect s.user_id,s.id from public.sites s\non conflict(site_id) do nothing;\n\ninsert into public.builder_templates(user_id,site_id,name,slug,template_type,is_default)\nselect s.user_id,s.id,'Default Site','default-site','site',true from public.sites s\non conflict(site_id,slug) do nothing;\n\ncreate or replace function public.validate_domain_verification_link()\nreturns trigger language plpgsql as $$\ndeclare ok boolean;\nbegin\n select exists(select 1 from public.domains d where d.id=new.domain_id and d.site_id=new.site_id and d.user_id=new.user_id) into ok;\n if not ok then raise exception 'domain verification must belong to the same site and user'; end if;\n return new;\nend $$;\n\ndrop trigger if exists validate_domain_verification_site on public.domain_verifications;\ncreate trigger validate_domain_verification_site\nbefore insert or update on public.domain_verifications\nfor each row execute function public.validate_domain_verification_link();\n\ninsert into public.system_checks(user_id,site_id,check_key,status,message)\nselect s.user_id,s.id,v.key,'pending','Not checked yet'\nfrom public.sites s cross join (values('media_library'),('domain_verification'),('security_headers'),('performance_defaults'),('redirects')) v(key)\non conflict(site_id,check_key) do nothing;